	private static final class LoserTree {

		private final RunCursor[] cursors;
		private final int leafCount;
		private final int[] winners;

		private LoserTree(RunCursor[] cursors) {
			this.cursors = cursors;
			int leaves = 1;
			while (leaves < cursors.length) {
				leaves <<= 1;
			}
			leafCount = leaves;
			winners = new int[leafCount << 1];
			Arrays.fill(winners, -1);
			for (int index = 0; index < cursors.length; index++) {
				winners[leafCount + index] = cursors[index].current == null ? -1 : index;
			}
			for (int node = leafCount - 1; node > 0; node--) {
				winners[node] = winner(winners[node << 1], winners[node << 1 | 1]);
			}
		}

		private int winner() {
			return winners[1];
		}

		private void updated(int cursor) {
			int node = leafCount + cursor;
			winners[node] = cursors[cursor].current == null ? -1 : cursor;
			while ((node >>= 1) > 0) {
				winners[node] = winner(winners[node << 1], winners[node << 1 | 1]);
			}
		}

		private int winner(int left, int right) {
			if (left < 0) {
				return right;
			}
			if (right < 0) {
				return left;
			}
			int comparison = Arrays.compareUnsigned(cursors[left].current.key, cursors[right].current.key);
			return comparison < 0 || comparison == 0 && left < right ? left : right;
		}
	}

	private void writeAssigned(DataOutputStream output, MutableEntry entry) throws IOException {
		long id;
		boolean persisted;
		if (CanonicalTermCodec.isNamespace(entry.key)) {
			id = idAllocator.next(ValueIds.T_PTR);
			persisted = true;
		} else {
			Value value = CanonicalTermCodec.decode(entry.key);
			id = InlineValueCodec.tryEncode(value, config);
			if (id != 0L) {
				inlineValues++;
				persisted = false;
			} else {
				id = assignedId(value, entry.key);
				persisted = true;
			}
		}
		if (persisted) {
			persistedValues++;
		}
		output.writeLong(entry.routeHash);
		output.writeLong(id);
		output.writeInt(entry.roles);
		output.writeInt(entry.key.length);
		output.write(entry.key);
	}

	private long assignedId(Value value, byte[] canonicalKey) {
		return switch (value) {
		case IRI ignored -> {
			long plannedId = predicateIdPlan.idFor(canonicalKey);
			yield plannedId == 0L ? idAllocator.next(ValueIds.T_URI) : plannedId;
		}
		case Literal literal -> idAllocator.nextLiteral(literal);
		case BNode ignored -> idAllocator.next(ValueIds.T_BNODE);
		case TripleTerm ignored -> idAllocator.next(ValueIds.T_TRIPLE);
		default -> throw new IllegalArgumentException("Unsupported RDF value type " + value.getClass().getName());
		};
	}

	private static void writeRunEntry(DataOutputStream output, MutableEntry entry) throws IOException {
		output.writeInt(entry.key.length);
		output.write(entry.key);
		output.writeLong(entry.routeHash);
		output.writeInt(entry.roles);
	}

	private static void deleteRuns(List<Path> runs) throws IOException {
		IOException failure = null;
		for (Path run : List.copyOf(runs)) {
			try {
				Files.deleteIfExists(run);
			} catch (IOException e) {
				if (failure == null) {
					failure = e;
				} else {
					failure.addSuppressed(e);
				}
			}
		}
		if (failure != null) {
			throw failure;
		}
	}

	private void checkCancelled() {
		if (Thread.currentThread().isInterrupted() || cancellationSignal.getAsBoolean()) {
			throw new CancellationException("LMDB bulk load was cancelled");
		}
	}

	private record ByteKey(byte[] bytes) {

		@Override
		public int hashCode() {
			return Arrays.hashCode(bytes);
		}

		@Override
		public boolean equals(Object object) {
			return object instanceof ByteKey other && Arrays.equals(bytes, other.bytes);
		}
	}

	private static final class MutableEntry {

		private final long routeHash;
		private int roles;
		private final byte[] key;

		private MutableEntry(long routeHash, int roles, byte[] key) {
			this.routeHash = routeHash;
			this.roles = roles;
			this.key = key;
		}
	}

	private static final class RunCursor implements AutoCloseable {

		private final DataInputStream input;
		private final Path path;
		private final boolean deleteWhenClosed;
		private MutableEntry current;
		private boolean closed;

		private RunCursor(Path path, BulkCompression compression, boolean deleteWhenClosed) throws IOException {
			this.path = path;
			this.deleteWhenClosed = deleteWhenClosed;
			input = BulkLz4.input(path, compression.codecFor(BulkArtifact.DICTIONARY));
		}

		private boolean advance() throws IOException {
			int length;
			try {
				length = input.readInt();
			} catch (EOFException e) {
				current = null;
				return false;
			}
			if (length < 0 || length > MAX_KEY_BYTES) {
				throw new IOException("Invalid dictionary run key length: " + length);
			}
			byte[] key = new byte[length];
			input.readFully(key);
			current = new MutableEntry(input.readLong(), input.readInt(), key);
			return true;
		}

		@Override
		public void close() throws IOException {
			if (closed) {
				return;
			}
			closed = true;
			try {
				input.close();
			} finally {
				if (deleteWhenClosed) {
					Files.deleteIfExists(path);
				}
			}
		}
	}

	private static final class IdAllocator {

		private final long[] nextByType = new long[ValueIds.T_TRIPLE + 1];

		private IdAllocator() {
			Arrays.fill(nextByType, 1L);
			nextByType[ValueIds.T_URI] = PredicateIdPlan.RESERVED_IDS + 1L;
		}

		private long next(int type) {
			return ValueIds.createId(type, nextByType[type]++);
		}

		private long nextLiteral(Literal literal) {
			long ordinal = nextByType[ValueIds.T_LITERAL]++;
			long encoded = ValueIds.createCoreLiteralReferenceId(ordinal, literal.getCoreDatatype());
			return encoded == 0L ? ValueIds.createId(ValueIds.T_LITERAL, ordinal) : encoded;
		}

	}

	@FunctionalInterface
	private interface EntryConsumer {
		void accept(MutableEntry entry) throws IOException;
	}
